'use strict';const TimelineToc=({index:a,mediaTypeFilter:f,metadataDates:e,year:b,month:c,day:d})=>`
    ${0===a||0<a&&e[a-1].year!==b?`
        <strong>${b}</strong>
        <div class='list-group'>
    `:""}

    ${0<a&&e[a-1].year===b&&e[a-1].month===c?`
            <a style="display:none" id="offcanvas_${b}-${c}-${d}" class="list-group-item list-group-item-action${0===a?" active":""}" href="#${b}-${c}-${d}"></a>
    `:`
            <a id="offcanvas_${b}-${c}-${d}" class="list-group-item list-group-item-action${0===a?" active":""}" href="#${b}-${c}-${d}">${(new Date(b,c-1,d)).format("mmm yyyy")}</a>
    `}
    
            <script type="text/javascript"${0<shashin.nonce.length?` nonce="${shashin.nonce}"`:""}>
                $("#offcanvas_${b}-${c}-${d}").on("click", function (e) {
                    e.preventDefault();
                    timelineSettings.jumpFromTimelineToc(e,"${b}-${c}-${d}","${f}")
                });
            </script>

    ${0<a&&a<e.length-1&&e[a+1].year!==b?"\n        </div>\n        <br>\n    ":""}
`,MapLinks=({metadata:a})=>`
    <a href="/map?lat=${a.lat}&lng=${a.lng}" target="_blank" class="bi-pin-fill" style="text-decoration: none;">&nbsp;${a.placeName}</a>
    <br>
    <a href="https://www.google.com/maps/search/?api=1&query=${a.lat}%2C${a.lng}" target="_blank" class="bi-google" style="text-decoration: none;">&nbsp;Google Maps link</a>
`,HeaderThumbnail=({metadata:a})=>`
    <img loading="lazy" src="${encodeURI(a.thumbnailUrlCentered)}" height="100" width="100" onError="Util.errorImg(this,\\'${a.title}\\',100)">
`,BatchHeaderThumbnail=({thumbnailImage:a,title:f})=>`
    <img loading="lazy" src="${a}" height="75" width="75" data-bs-toggle="tooltip" data-bs-placement="top" title="${f}" onError="Util.errorImg(this,\'${f}\',75)">
`;

